import { test, expect } from '@playwright/test';

test.describe('User Authentication', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should pre-fill username if previously logged in', async ({ page }) => {
    // Simulate a previous login
    await page.fill('input[name="username"]', 'testuser');
    await page.fill('input[name="password"]', 'password123');
    await page.click('button[type="submit"]');

    // Log out to test the pre-fill functionality
    await page.click(getByRole('button', { name: /logout/i }));

    // Navigate back to login page
    await page.goto('/login');

    // Check if the username is pre-filled
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toHaveValue('testuser');
  });

  test('should not pre-fill username if not previously logged in', async ({ page }) => {
    // Navigate to login page without logging in
    await page.goto('/login');

    // Check if the username input is empty
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toHaveValue('');
  });
});
